// @name Reversi
// @background #f2efe7
// @refresh 3600
// Reversi (Othello) for a touch screen: tap a square to place a disc and turn
// every line of the other color it closes in. Play the computer or a friend.
// The game in progress is kept on the frame.
import { replay, bestMove, counts, isLegal, toCell } from './logic'
import { highContrast, canvasOf, Button, OptionsPage, Title, titleSize, textH, fitText, fitWidth, withText, roundOf, RoundTable, RoundKey, RoundButton } from './ui'

const THEMES = {
  color: {
    page: 'bg-[#f2efe7] text-[#1f2a2e]',
    muted: 'text-[#5f6b66]',
    button: 'bg-[#e2ddd0] text-[#1f2a2e] active:bg-[#d3ccba]',
    primary: 'bg-[#2e5e4e] text-white active:bg-[#3a735f]',
    on: 'bg-[#2e5e4e] text-white',
    off: 'bg-[#e2ddd0] text-[#1f2a2e]',
    board: '#2e5e4e',
    line: '#1f453a',
    edge: '#1a3a31',
    discs: ['', '#1c1f22', '#f7f5ef'],
    discEdge: ['', '#000000', '#bdb7aa'],
    hint: '#173328',
    last: '#d9734e',
  },
  high: {
    page: 'bg-white text-black',
    muted: 'text-black',
    button: 'bg-white text-black border-2 border-black',
    primary: 'bg-black text-white',
    on: 'bg-black text-white',
    off: 'bg-white text-black border-2 border-black',
    board: '#ffffff',
    line: '#000000',
    edge: '#000000',
    discs: ['', '#000000', '#ffffff'],
    discEdge: ['', '#000000', '#000000'],
    hint: '#000000',
    last: '',
  },
}
const NAMES = ['', 'Black', 'White']

const OPTIONS = [
  { field: 'opponent', label: 'Opponent', options: [['computer', 'Computer'], ['human', 'Two players']] },
  { field: 'level', label: 'Computer level', options: [['easy', 'Easy'], ['medium', 'Medium'], ['hard', 'Hard']] },
  { field: 'side', label: 'You play', options: [['black', 'Black (first)'], ['white', 'White']] },
  { field: 'hints', label: 'Legal moves', options: [['show', 'Show'], ['hide', 'Hide']] },
]

const settingsOf = (app) => ({
  vsComputer: (app.state.opponent || 'computer') !== 'human',
  level: app.state.level || 'medium',
  human: app.state.side === 'white' ? 2 : 1,
  hints: app.state.hints !== 'hide',
})

// The game in progress, kept in the scene's private `game` field: the squares
// played, 0..63. The board is rebuilt from them, so undo drops the last ones.
type Game = { moves: number[] }
const loadGame = (app): Game => {
  const g = app.state.game
  return g && Array.isArray(g.moves) ? g : { moves: [] }
}
const save = (game: Game) => frameos.setState('game', game)

// The computer's moves while it is its turn (twice or more when you have to
// pass).
const settle = (app, game: Game): Game => {
  const { vsComputer, level, human } = settingsOf(app)
  if (!vsComputer) return game
  let state = replay(game.moves)
  let moves = game.moves
  while (!state.result && state.toMove !== human) {
    const square = bestMove(state.board, state.toMove, level, Math.random)
    if (square < 0) break
    moves = [...moves, square]
    state = replay(moves)
  }
  return moves === game.moves ? game : { moves }
}

// What each square shows, one signal a square, and the panel's lines: a tap
// runs only the squares and lines that read what it changed, not get(). The
// game itself stays in the scene's `game` field.
// A square's look: "" empty, "h" a legal move's dot, "1" / "2" a disc, and
// "1L" / "2L" the last disc played.
const looks = Array.from({ length: 64 }, () => signal(''))
const blackCount = signal(0)
const whiteCount = signal(0)
const status = signal('')
const statusDisc = signal(0)
const note = signal('')
const over = signal(false)

// Every signal from the game in progress and the settings.
const show = (app) => {
  const game = loadGame(app)
  const settings = settingsOf(app)
  const state = replay(game.moves)
  const last = state.played ? game.moves[state.played - 1] : -1
  for (let square = 0; square < 64; square++) {
    const cell = toCell(square)
    const who = state.board[cell]
    looks[square].value = who === 1 || who === 2 ? `${who}${square === last ? 'L' : ''}`
      : settings.hints && !state.result && isLegal(state.board, cell, state.toMove) ? 'h' : ''
  }
  const { black, white } = counts(state.board)
  blackCount.value = black
  whiteCount.value = white
  const { vsComputer, human } = settings
  const name = (who: number) => (vsComputer ? (who === human ? 'You' : 'The computer') : NAMES[who])
  let line
  if (state.result === 3) line = `A draw, ${black} all`
  else if (state.result) {
    const hi = Math.max(black, white)
    const lo = Math.min(black, white)
    line = vsComputer ? (state.result === human ? `You win ${hi} to ${lo}!` : `The computer wins ${hi} to ${lo}`) : `${NAMES[state.result]} wins ${hi} to ${lo}!`
  } else line = vsComputer ? 'Your turn' : `${NAMES[state.toMove]} to play`
  status.value = line
  statusDisc.value = state.result === 3 ? 0 : state.result || state.toMove
  note.value = !state.result && state.passed ? `${name(state.passed)} had no move` : ''
  over.value = !!state.result
}

const place = (app, square: number) => {
  const game = loadGame(app)
  const state = replay(game.moves)
  const { vsComputer, human } = settingsOf(app)
  if (state.result || (vsComputer && state.toMove !== human)) return
  if (!isLegal(state.board, toCell(square), state.toMove)) return
  save(settle(app, { moves: [...game.moves, square] }))
  show(app)
}

// Back to your last turn against the computer, one move with two players.
// When that takes away the computer's opening move, it plays one again.
const undo = (app) => {
  const game = loadGame(app)
  const { vsComputer, human } = settingsOf(app)
  const moves = game.moves.slice()
  if (!moves.length) return
  moves.pop()
  if (vsComputer) {
    while (moves.length && replay(moves).toMove !== human) moves.pop()
  }
  save(settle(app, { moves }))
}

const restart = (app) => {
  save(settle(app, { moves: [] }))
  frameos.remember('page', null)
}

// Buttons on frames without a touch screen: back is undo, forward a new game
// once this one is over. On a keyboard U undoes and N starts again.
export function onEvent(app, context) {
  const event = context.event
  if (event === 'back') undo(app)
  else if (event === 'forward') {
    if (!replay(loadGame(app).moves).result) return false
    restart(app)
  } else if (event === 'keyDown') {
    const p = context.payload || {}
    const key = String(p.key || '').toLowerCase()
    if (p.ctrl || p.alt || p.meta) return false
    if (key === 'u' || key === 'backspace') undo(app)
    else if (key === 'n') restart(app)
    else return false
  } else return false
  return true
}

// One square, drawn from its look: a disc (with a mark when it was the last
// one played), the dot of a legal move, or nothing.
const Square = memo(({ square, t }) => {
  const look = looks[square].value
  const cx = (square % 8) * 100 + 50
  const cy = Math.floor(square / 8) * 100 + 50
  if (look === 'h') return <g><circle cx={cx} cy={cy} r={13} fill="none" stroke={t.hint} strokeWidth={5} /></g>
  if (!look) return <g />
  const who = Number(look[0])
  return (
    <g>
      <circle cx={cx} cy={cy} r={40} fill={t.discs[who]} stroke={t.discEdge[who]} strokeWidth={who === 2 ? 6 : 3} />
      {look[1] === 'L' ? (t.last
        ? <circle cx={cx} cy={cy} r={11} fill={t.last} />
        : <rect x={cx - 10} y={cy - 10} width={20} height={20} fill={t.discs[3 - who]} />) : null}
    </g>
  )
})

// The board, 100 units a square: the discs, the moves the player to move
// may make (small dots) and a mark on the last disc played.
const Board = ({ t, size }) => {
  const parts = []
  for (let i = 1; i < 8; i++) {
    parts.push(<line x1={i * 100} y1={0} x2={i * 100} y2={800} stroke={t.line} strokeWidth={4} />)
    parts.push(<line x1={0} y1={i * 100} x2={800} y2={i * 100} stroke={t.line} strokeWidth={4} />)
  }
  for (const [x, y] of [[200, 200], [600, 200], [200, 600], [600, 600]]) {
    parts.push(<circle cx={x} cy={y} r={9} fill={t.line} />)
  }
  for (let square = 0; square < 64; square++) parts.push(<Square square={square} t={t} />)
  return (
    <svg viewBox="-10 -10 820 820" width={size} height={size}>
      <rect x={-8} y={-8} width={816} height={816} rx={14} fill={t.board} stroke={t.edge} strokeWidth={6} />
      {parts}
    </svg>
  )
}

const Disc = ({ t, who, size }) => (
  <svg viewBox="0 0 40 40" className={`w-[${size}px] h-[${size}px]`}>
    <circle cx={20} cy={20} r={16} fill={t.discs[who]} stroke={who === 2 ? '#000000' : t.discEdge[who]} strokeWidth={who === 2 ? 3 : 2} />
  </svg>
)

// The panel's parts that a move changes, each reading its signals.
const Tally = memo(({ ui, t }) => {
  const discSize = Math.round(ui.big * 1.15)
  return (
    <div className={`flex items-center gap-[${ui.gap}px] text-[${ui.big}px] font-bold`}>
      <Disc t={t} who={1} size={discSize} />
      <span>{blackCount.value}</span>
      <span className="w-[8px]" />
      <Disc t={t} who={2} size={discSize} />
      <span>{whiteCount.value}</span>
    </div>
  )
})
const Status = memo(({ ui, t }) => (
  <div className="flex flex-col">
    <div className={`flex items-center gap-[${Math.round(ui.gap * 0.8)}px]`}>
      {statusDisc.value ? <Disc t={t} who={statusDisc.value} size={Math.round(ui.text * 1.2)} /> : null}
      <span className={`text-[${ui.text}px] font-semibold leading-tight`}>{status.value}</span>
    </div>
    {note.value ? <span className={`text-[${ui.small}px] ${t.muted}`}>{note.value}</span> : null}
  </div>
))
const NewButton = memo(({ ui, t, app, grow }) => (
  <Button ui={ui} grow={grow} className={over.value ? t.primary : t.button} onClick={() => { restart(app); show(app) }}>New game</Button>
))
const UndoButton = memo(({ ui, t, app, grow }) => (
  <Button ui={ui} grow={grow} className={t.button} onClick={() => { undo(app); show(app) }}>Undo</Button>
))

// Round: the status on one line, the note (a pass) in its place when there is one.
const RoundStatus = memo(({ ui, t }) => (
  <span className={`text-[${ui.small}px] font-semibold ${note.value ? t.muted : ''}`}>{note.value || status.value}</span>
))
const RoundNew = memo(({ room, ui, t, app }) => (
  <RoundButton room={room} ui={ui} className={over.value ? t.primary : t.button} onClick={() => { restart(app); show(app) }}>New game</RoundButton>
))

// The sizes only change with the canvas: the same object while it does not,
// so the memo()'d parts are not run again for a new one.
let lastUi = null
const stableUi = (ui) => (lastUi && lastUi.W === ui.W && lastUi.H === ui.H ? lastUi : (lastUi = ui))

export function get(app, context) {
  const ui = stableUi(canvasOf(app, context))
  const t = highContrast(app) ? THEMES.high : THEMES.color
  const settings = settingsOf(app)
  const room = roundOf(context)

  if (frameos.recall('page') === 'options') {
    const rows = OPTIONS.filter((row) => settings.vsComputer || (row.field !== 'level' && row.field !== 'side')).map((row) => ({
      ...row,
      value: app.state[row.field] || row.options[0][0],
    }))
    return <OptionsPage ui={ui} t={t} title="Reversi" rows={rows} room={room}
      onClose={() => frameos.remember('page', null)} onNew={() => restart(app)} />
  }

  // The computer opens when you play white, or moves after a settings change.
  let game = loadGame(app)
  const settled = settle(app, game)
  if (settled !== game) {
    game = settled
    save(game)
  }
  show(app)

  // Side by side or stacked, whichever gives the bigger board.
  const sideW = Math.round(Math.max(ui.W * 0.27, ui.text * 9))
  const sideSize = Math.min(ui.W - sideW - ui.pad * 3, ui.H - ui.pad * 2)
  const stackSize = Math.min(ui.W - ui.pad * 2, ui.H - ui.pad * 2 - ui.gap * 2 - ui.button * 2)
  const side = sideSize >= stackSize
  const size = room ? room.side : Math.floor(side ? sideSize : stackSize)

  const board = (
    <div className={`w-[${size}px] h-[${size}px] shrink-0`}
      onClick={(e) => {
        const col = Math.floor(((e.localX / e.width) * 820 - 10) / 100)
        const row = Math.floor(((e.localY / e.height) * 820 - 10) / 100)
        if (col >= 0 && col < 8 && row >= 0 && row < 8) place(app, row * 8 + col)
      }}>
      <Board t={t} size={size} />
    </div>
  )
  const tally = <Tally ui={ui} t={t} />
  const statusBlock = <Status ui={ui} t={t} />
  const optionsAction = () => frameos.remember('page', 'options')
  const buttons = [
    <UndoButton ui={ui} t={t} app={app} grow={!side} />,
    <NewButton ui={ui} t={t} app={app} grow={!side} />,
    <Button ui={ui} grow={!side} className={t.button} onClick={optionsAction}>Options</Button>,
  ]

  if (room) {
    // Round: the board in the square inside the circle, the count and whose
    // turn it is in the arc above, Undo and Options beside it, a new game below.
    const key = Math.min(56, room.x - 14)
    return (
      <RoundTable room={room} t={t} board={board}
        top={<div className="flex flex-col items-center">{tally}<RoundStatus ui={ui} t={t} /></div>}
        left={<RoundKey size={key} t={t} icon="undo" onClick={() => { undo(app); show(app) }} />}
        right={<RoundKey size={key} t={t} icon="more" onClick={() => frameos.remember('page', 'options')} />}
        bottom={<RoundNew room={room} ui={ui} t={t} app={app} />} />
    )
  }
  if (side) {
    // The column beside the board. Where it is short (a 320x240 panel), New
    // game over Undo and Options side by side.
    const colW = ui.W - ui.pad * 3 - size
    const named = titleSize(ui, colW, 'Reversi')
    const full = textH('Reversi', `text-[${named}px] font-bold leading-tight`, named, colW) + ui.big * 1.25 + ui.text * 1.25 + ui.button * 3 + ui.gap * 7
    const tight = full > ui.H - ui.pad * 2
    const halfText = fitText('Options', Math.floor((colW - ui.gap) / 2), ui.text)
    const half = withText(ui, halfText)
    return (
      <div className={`flex w-full h-full p-[${ui.pad}px] gap-[${ui.pad}px] items-center ${t.page}`}>
        {board}
        <div className={`flex-1 h-full flex flex-col gap-[${ui.gap}px]`}>
          <Title ui={ui} width={colW} line={tight}>Reversi</Title>
          {tally}
          <div className="flex-1" />
          {statusBlock}
          <div className="flex-1" />
          {tight ? (
            <div className={`space-y-[${ui.gap}px]`}>
              <NewButton ui={ui} t={t} app={app} grow={false} />
              {halfText >= 13 ? (
                <div className={`flex gap-[${ui.gap}px]`}>
                  <UndoButton ui={half} t={t} app={app} grow={true} />
                  <Button ui={half} grow className={t.button} onClick={optionsAction}>Options</Button>
                </div>
              ) : (
                <div className="flex justify-between">
                  <RoundKey size={ui.button} t={t} icon="undo" square onClick={() => { undo(app); show(app) }} />
                  <RoundKey size={ui.button} t={t} icon="more" square onClick={optionsAction} />
                </div>
              )}
            </div>
          ) : (
            <div className={`space-y-[${ui.gap}px]`}>{buttons}</div>
          )}
        </div>
      </div>
    )
  }
  // The row under the board: the three words where each fits a third of it,
  // else (a watch) Undo and Options as keys with their glyphs beside New game.
  const keys = (ui.W - ui.pad * 2 - ui.gap * 2) / 3 < fitWidth('New game', ui.text)
  return (
    <div className={`flex flex-col w-full h-full p-[${ui.pad}px] gap-[${ui.gap}px] items-center ${t.page}`}>
      {ui.H > ui.W * 1.3 ? <span className={`w-full text-[${ui.title}px] font-bold leading-tight`}>Reversi</span> : null}
      <div className={`flex items-center justify-between w-full h-[${ui.button}px]`}>
        {statusBlock}
        {tally}
      </div>
      <div className="flex-1 flex items-center justify-center">{board}</div>
      {keys ? (
        <div className={`flex w-full gap-[${ui.gap}px]`}>
          <RoundKey size={ui.button} t={t} icon="undo" square onClick={() => { undo(app); show(app) }} />
          <NewButton ui={ui} t={t} app={app} grow={true} />
          <RoundKey size={ui.button} t={t} icon="more" square onClick={optionsAction} />
        </div>
      ) : (
        <div className={`flex w-full gap-[${ui.gap}px]`}>{buttons}</div>
      )}
    </div>
  )
}

