// Reversi (Othello) rules and the computer player. Pure: no frameos calls, so
// it can be checked with plain node.
//
// The board is kept with a border, 10x10, so a walk off the edge meets a
// border cell instead of needing bounds checks: cell = (row + 1) * 10 + col + 1.
// 0 empty, 1 black, 2 white, 3 the border. Black moves first. A game is the
// list of squares played (0..63, row * 8 + col); a player with no move passes
// by itself, so the list holds no passes.

const BORDER = 3
const DIRS = [-11, -10, -9, -1, 1, 9, 10, 11]
export const toCell = (square: number) => ((square >> 3) + 1) * 10 + (square & 7) + 1
export const toSquare = (cell: number) => (Math.floor(cell / 10) - 1) * 8 + (cell % 10) - 1

// The value of holding each square: corners are gold, the squares next to an
// empty corner give it away, edges are good.
const WEIGHTS = [
  120, -20, 20, 5, 5, 20, -20, 120,
  -20, -40, -5, -5, -5, -5, -40, -20,
  20, -5, 15, 3, 3, 15, -5, 20,
  5, -5, 3, 3, 3, 3, -5, 5,
  5, -5, 3, 3, 3, 3, -5, 5,
  20, -5, 15, 3, 3, 15, -5, 20,
  -20, -40, -5, -5, -5, -5, -40, -20,
  120, -20, 20, 5, 5, 20, -20, 120,
]
const CELL_WEIGHT = new Int16Array(100)
for (let s = 0; s < 64; s++) CELL_WEIGHT[toCell(s)] = WEIGHTS[s]
// The squares next to each corner, which stop costing once it is taken.
const CORNERS = [
  [11, 12, 21, 22],
  [18, 17, 28, 27],
  [81, 82, 71, 72],
  [88, 87, 78, 77],
]
// Squares in the order the search tries them: the best-valued first.
const ORDER = Array.from({ length: 64 }, (_, s) => toCell(s)).sort((a, b) => CELL_WEIGHT[b] - CELL_WEIGHT[a])

export function newBoard() {
  const b = new Int8Array(100).fill(BORDER)
  for (let s = 0; s < 64; s++) b[toCell(s)] = 0
  b[toCell(27)] = 2
  b[toCell(36)] = 2
  b[toCell(28)] = 1
  b[toCell(35)] = 1
  return b
}

// Whether `player` may play `cell` (it must turn at least one disc).
export function isLegal(b: Int8Array, cell: number, player: number) {
  if (b[cell] !== 0) return false
  const other = 3 - player
  for (let d = 0; d < 8; d++) {
    const dir = DIRS[d]
    let c = cell + dir
    if (b[c] !== other) continue
    c += dir
    while (b[c] === other) c += dir
    if (b[c] === player) return true
  }
  return false
}

// Every legal cell for `player`, in search order.
export function legalCells(b: Int8Array, player: number) {
  const out: number[] = []
  for (let i = 0; i < 64; i++) {
    const cell = ORDER[i]
    if (b[cell] === 0 && isLegal(b, cell, player)) out.push(cell)
  }
  return out
}

function countLegal(b: Int8Array, player: number) {
  let n = 0
  for (let i = 0; i < 64; i++) {
    const cell = ORDER[i]
    if (b[cell] === 0 && isLegal(b, cell, player)) n++
  }
  return n
}

// Plays `cell` for `player`, turning the discs it closes in. Answers the
// cells turned (to take the move back), or null when it is not a move.
export function play(b: Int8Array, cell: number, player: number, flipped: number[]) {
  const other = 3 - player
  const start = flipped.length
  for (let d = 0; d < 8; d++) {
    const dir = DIRS[d]
    let c = cell + dir
    while (b[c] === other) c += dir
    if (b[c] !== player || c === cell + dir) continue
    for (let x = cell + dir; x !== c; x += dir) {
      b[x] = player
      flipped.push(x)
    }
  }
  if (flipped.length === start) return 0
  b[cell] = player
  return flipped.length - start
}

function unplay(b: Int8Array, cell: number, flipped: number[], count: number, player: number) {
  const other = 3 - player
  b[cell] = 0
  for (let i = 0; i < count; i++) b[flipped.pop() as number] = other
}

export function counts(b: Int8Array) {
  let black = 0
  let white = 0
  for (let s = 0; s < 64; s++) {
    const v = b[toCell(s)]
    if (v === 1) black++
    else if (v === 2) white++
  }
  return { black, white }
}

// The game from its moves: the board, who moves next, whether the side to
// move just got the turn back because the other had no move, and the result
// (0 on, 1 black won, 2 white won, 3 a draw).
export function replay(moves: number[]) {
  const b = newBoard()
  let toMove = 1
  let passed = 0
  let played = 0
  const flipped: number[] = []
  for (const square of moves) {
    const cell = toCell(square)
    if (!isLegal(b, cell, toMove)) break
    play(b, cell, toMove, flipped)
    flipped.length = 0
    played++
    toMove = 3 - toMove
    passed = 0
    if (!countLegal(b, toMove)) {
      passed = toMove
      toMove = 3 - toMove
    }
  }
  let result = 0
  if (!countLegal(b, toMove)) {
    const { black, white } = counts(b)
    result = black > white ? 1 : white > black ? 2 : 3
    passed = 0
  }
  return { board: b, toMove, passed, result, played }
}

// How hard the computer plays: plies looked ahead, the node budget, and for
// the easiest level how far below the best a move may be and still be picked.
export const LEVELS = {
  easy: { depth: 1, nodes: 400, noise: 40, endgame: 0 },
  medium: { depth: 2, nodes: 1500, noise: 6, endgame: 6 },
  hard: { depth: 4, nodes: 4000, noise: 0, endgame: 10 },
}

const WIN = 100000

// What a position is worth to `player`: the squares held (corner neighbours
// count only while their corner is empty), and how many moves each side has.
function evaluate(b: Int8Array, player: number) {
  const other = 3 - player
  let score = 0
  for (let i = 0; i < 64; i++) {
    const cell = ORDER[i]
    const v = b[cell]
    if (v === player) score += CELL_WEIGHT[cell]
    else if (v === other) score -= CELL_WEIGHT[cell]
  }
  for (let k = 0; k < 4; k++) {
    const corner = CORNERS[k]
    if (b[corner[0]] === 0) continue
    // The corner is taken: its neighbours no longer give it away.
    for (let j = 1; j < 4; j++) {
      const v = b[corner[j]]
      if (v === player) score -= CELL_WEIGHT[corner[j]]
      else if (v === other) score += CELL_WEIGHT[corner[j]]
    }
  }
  const mine = countLegal(b, player)
  const theirs = countLegal(b, other)
  return score + 8 * (mine - theirs)
}

function discDiff(b: Int8Array, player: number) {
  const { black, white } = counts(b)
  return player === 1 ? black - white : white - black
}

// The computer's square (0..63) for `player`, or -1 with no move.
export function bestMove(board: Int8Array, player: number, level: string, random: () => number) {
  const cfg = LEVELS[level] || LEVELS.medium
  const b = Int8Array.from(board)
  const flipped: number[] = []
  let empties = 0
  for (let s = 0; s < 64; s++) if (b[toCell(s)] === 0) empties++
  let toEnd = empties <= cfg.endgame
  let nodes = 0
  let aborted = false

  const search = (depth: number, alpha: number, beta: number, who: number, passedBefore: boolean): number => {
    nodes++
    if (nodes > cfg.nodes) {
      aborted = true
      return 0
    }
    if (depth === 0 && !toEnd) return evaluate(b, who)
    const moves = legalCells(b, who)
    if (!moves.length) {
      if (passedBefore) {
        const diff = discDiff(b, who)
        return diff > 0 ? WIN + diff : diff < 0 ? -WIN + diff : 0
      }
      return -search(depth, -beta, -alpha, 3 - who, true)
    }
    let best = -WIN * 2
    for (const cell of moves) {
      const n = play(b, cell, who, flipped)
      const value = -search(depth - 1, -beta, -alpha, 3 - who, false)
      unplay(b, cell, flipped, n, who)
      if (aborted) return 0
      if (value > best) best = value
      if (value > alpha) alpha = value
      if (alpha >= beta) break
    }
    return best
  }

  let order = legalCells(b, player)
  if (!order.length) return -1
  if (order.length === 1) return toSquare(order[0])

  // One pass over the root's moves at `depth`; false when the budget ran out.
  let values: Record<number, number> = {}
  const pass = (depth: number) => {
    const found: Record<number, number> = {}
    let alpha = -WIN * 2
    for (const cell of order) {
      const n = play(b, cell, player, flipped)
      const value = -search(depth - 1, -WIN * 2, cfg.noise ? WIN * 2 : -alpha, 3 - player, false)
      unplay(b, cell, flipped, n, player)
      if (aborted) return false
      found[cell] = value
      if (value > alpha) alpha = value
    }
    values = found
    order = order.slice().sort((x, y) => values[y] - values[x])
    return true
  }

  // Near the end, play it out exactly if the budget allows; otherwise (and
  // before that) look `depth` plies ahead, one more at a time.
  if (toEnd) {
    if (pass(1)) return toSquare(order[0])
    toEnd = false
    aborted = false
    nodes = 0
  }
  for (let depth = 1; depth <= cfg.depth; depth++) {
    if (!pass(depth)) break
  }
  if (!Object.keys(values).length) return toSquare(order[0])
  const best = values[order[0]]
  if (cfg.noise && best < WIN / 2) {
    const near = order.filter((cell) => values[cell] >= best - cfg.noise)
    if (near.length) return toSquare(near[Math.floor(random() * near.length)])
  }
  return toSquare(order[0])
}

