// The parts every game here shares: the contrast rule, the canvas's size,
// buttons and the options page. Each game carries its own copy of this file.

// High contrast where the panel shows no color (black and white, greys), or
// when the scene's Contrast setting asks for it.
export const highContrast = (app) => {
  const mode = app.state.contrast || 'auto'
  return mode === 'high' || (mode === 'auto' && app.frame.color === false)
}

export const clamp = (n: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, n))

// The canvas being drawn on (already turned with the frame) and the sizes of
// the text and buttons, worked out from its shorter side so the same scene
// reads well on a 480x480 square and on a 1600x1200 panel.
export const canvasOf = (app, context) => {
  const W = Math.round(context?.imageWidth ?? app.frame.width)
  const H = Math.round(context?.imageHeight ?? app.frame.height)
  const short = Math.min(W, H)
  const unit = short / 100
  return {
    W,
    H,
    portrait: H > W * 1.05,
    pad: Math.round(clamp(unit * 3.5, 10, 48)),
    gap: Math.round(clamp(unit * 2, 6, 24)),
    title: Math.round(clamp(unit * 7, 24, 72)),
    big: Math.round(clamp(unit * 5.6, 20, 60)),
    text: Math.round(clamp(unit * 4.4, 16, 44)),
    small: Math.round(clamp(unit * 3.4, 13, 34)),
    button: Math.round(clamp(unit * 11, 44, 110)),
  }
}

// A button: a box with an onClick, at least a finger tall.
export const Button = ({ ui, className, onClick, children, grow }: any) => (
  <div
    className={`${grow ? 'flex-1 basis-0 min-w-0' : ''} h-[${ui.button}px] px-[${Math.round(ui.text * 0.5)}px] rounded-xl flex items-center justify-center whitespace-nowrap text-[${ui.text}px] font-semibold ${className}`}
    onClick={onClick}
  >
    {children}
  </div>
)

// One setting as a row of buttons, the chosen one lit. `options` is a list
// of [value, label].
export const Choice = ({ ui, t, label, value, options, onPick }: any) => (
  <div className="flex flex-col gap-1">
    <span className={`text-[${ui.small}px] ${t.muted}`}>{label}</span>
    <div className={`flex gap-[${Math.round(ui.gap * 0.7)}px]`}>
      {options.map(([v, text]) => (
        <div
          className={`flex-1 h-[${Math.round(ui.button * 0.85)}px] rounded-xl flex items-center justify-center text-[${ui.small}px] font-semibold ${String(v) === String(value) ? t.on : t.off}`}
          onClick={() => onPick(v)}
        >
          {text}
        </div>
      ))}
    </div>
  </div>
)

// A number setting: minus, the value, plus.
export const Stepper = ({ ui, t, label, value, min, max, step, onPick }: any) => {
  const h = Math.round(ui.button * 0.85)
  const key = (text: string, next: number) => (
    <div
      className={`w-[${Math.round(h * 1.4)}px] h-[${h}px] rounded-xl flex items-center justify-center text-[${ui.big}px] font-bold ${t.off}`}
      onClick={() => onPick(clamp(next, min, max))}
    >
      {text}
    </div>
  )
  return (
    <div className={`flex items-center gap-[${ui.gap}px]`}>
      <span className={`flex-1 text-[${ui.text}px]`}>{label}</span>
      {key('−', value - (step || 1))}
      <span className={`w-[${Math.round(ui.text * 2.6)}px] text-center text-[${ui.text}px] font-bold`}>{String(value)}</span>
      {key('+', value + (step || 1))}
    </div>
  )
}

// The options page: the game's settings as rows of buttons, written to the
// scene's public fields (the same ones the frame's settings show), and a
// button to start a new game with them. A row with `min` is a number.
export const OptionsPage = ({ ui, t, title, rows, onClose, onNew, room }: any) => room ? (
  <RoundTable room={room} t={t}
    top={<span className={`text-[${ui.big}px] font-bold`}>{title}</span>}
    board={
      <div className="w-full h-full overflow-y-auto">
        <div className={`flex flex-col gap-[${ui.gap}px]`}>
          {rows.map((row) =>
            row.min !== undefined ? (
              <Stepper ui={ui} t={t} label={row.label} value={row.value} min={row.min} max={row.max} step={row.step}
                onPick={(v) => frameos.setState(row.field, v)} />
            ) : (
              <Choice ui={ui} t={t} label={row.label} value={row.value} options={row.options}
                onPick={(v) => frameos.setState(row.field, v)} />
            ),
          )}
        </div>
      </div>
    }
    left={<RoundKey size={Math.min(56, room.x - 14)} t={t} icon="back" onClick={onClose} />}
    bottom={<RoundButton room={room} ui={ui} className={t.primary} onClick={onNew}>New game</RoundButton>} />
) : (
  <div className={`flex flex-col w-full h-full p-[${ui.pad}px] gap-[${ui.gap}px] ${t.page}`}>
    <div className="flex items-center justify-between">
      <span className={`text-[${ui.title}px] font-bold`}>{title}</span>
    </div>
    <div className="flex-1 overflow-y-auto">
      <div className={`flex flex-col gap-[${ui.gap}px]`}>
        {rows.map((row) =>
          row.min !== undefined ? (
            <Stepper ui={ui} t={t} label={row.label} value={row.value} min={row.min} max={row.max} step={row.step}
              onPick={(v) => frameos.setState(row.field, v)} />
          ) : (
            <Choice ui={ui} t={t} label={row.label} value={row.value} options={row.options}
              onPick={(v) => frameos.setState(row.field, v)} />
          ),
        )}
      </div>
    </div>
    <div className={`flex gap-[${ui.gap}px]`}>
      <Button ui={ui} grow className={t.button} onClick={onClose}>Back</Button>
      <Button ui={ui} grow className={t.primary} onClick={onNew}>New game</Button>
    </div>
  </div>
)

// The game's name over a side panel `width` wide: as large as the titles
// elsewhere, smaller when its longest word would not fit (a name of two
// words may take two lines), or with `line` when the whole name would not.
export const titleSize = (ui, width: number, name: string, line = false) => {
  const longest = line ? name.length : Math.max(...name.split(' ').map((word) => word.length))
  return Math.floor(Math.min(ui.title, width / (longest * 0.6)))
}
export const Title = ({ ui, width, line, children }: any) => (
  <span className={`text-[${titleSize(ui, width, String(children), line)}px] font-bold leading-tight`}>{children}</span>
)

// How wide a text is at `size` px: the buttons' words as wide as Ubuntu Bold
// sets them (a bold the frame thickens from the regular face is a little
// narrower), anything else at about 0.62 of the size a letter.
const EM = { Undo: 2.51, New: 2.12, Finish: 2.81, Options: 3.81, 'New game': 4.96, 'New puzzle': 5.46 }
export const wordsW = (text: string, size: number) => (EM[text] ?? String(text).length * 0.62) * size

// How many lines a text takes at `size` px in a box `width` wide, wrapped at spaces.
export const linesOf = (text: string, size: number, width: number) => {
  let lines = 1
  let x = 0
  for (const word of String(text).split(' ')) {
    const w = wordsW(word, size)
    if (x > 0 && x + size * 0.25 + w > width) {
      lines++
      x = w
    } else x += (x > 0 ? size * 0.25 : 0) + w
  }
  return lines
}

// How wide a Button holding `text` at `size` px is at the least (its padding
// is half the size on each side), and the largest size up to `max` at which
// a button `width` wide holds it.
export const fitWidth = (text: string, size: number) => (wordsW(text, 1) + 1) * size
export const fitText = (text: string, width: number, max: number) => Math.floor(Math.min(max, width / fitWidth(text, 1)))

// How tall a text is, set in `className` (at `size` px) into `width`: the
// layout's own typesetting where the runtime measures it, else estimated.
export const textH = (text: string, className: string, size: number, width: number) => {
  try {
    if (typeof frameos.measureText === 'function') return frameos.measureText([text], { className, width })[0]
  } catch (e) {}
  return linesOf(text, size, width) * size * 1.25
}

// The sizes with the buttons' words at `text` px, the same object while they
// stay the same (what the memo()'d buttons are given stays equal).
export const withText = (ui, text: number) => (ui.text === text ? ui : ui._text && ui._text.text === text ? ui._text : (ui._text = { ...ui, text }))

// A round panel (context.round: only the circle shows): the square inside
// the circle for the board, the arcs above and below it and the two sides.
// `chord(dy)` is how wide a row may be `dy` px above or below the middle,
// 12 px in from the rim. Null on every other panel.
export const roundOf = (context) => {
  if (context?.round !== true) return null
  const W = Math.round(context.imageWidth)
  const H = Math.round(context.imageHeight)
  const r = Math.min(W, H) / 2 - 12
  const side = Math.floor(r * Math.SQRT2)
  const chord = (dy: number) => Math.floor(2 * Math.sqrt(Math.max(0, r * r - dy * dy)))
  return { W, H, r, side, x: Math.round((W - side) / 2), y: Math.round((H - side) / 2), chord }
}

// A round button for a side of the circle: an icon ('undo', 'more', 'back');
// `square`, a key in a row of buttons where their words would not fit.
const ICONS = {
  undo: 'M9 4 L4 9 L9 14 M4 9 H14 A5 5 0 0 1 14 19 H10',
  back: 'M15 4 L7 12 L15 20',
}
// The text color of a theme's classes, for an icon drawn in it.
const inkOf = (classes: string) => {
  const m = /(?:^| )text-\[(#[0-9a-fA-F]{3,8})\]/.exec(classes)
  return m ? m[1] : / text-white|^text-white/.test(classes) ? '#ffffff' : '#000000'
}
export const RoundKey = ({ size, t, icon, onClick, square }: any) => (
  <div className={`w-[${size}px] h-[${size}px] shrink-0 ${square ? 'rounded-xl' : 'rounded-full'} flex items-center justify-center ${t.button}`} onClick={onClick}>
    <svg viewBox="0 0 24 24" width={Math.round(size * 0.5)} height={Math.round(size * 0.5)}>
      {icon === 'more'
        ? <g fill={inkOf(t.button)}><circle cx={5} cy={12} r={2.4} /><circle cx={12} cy={12} r={2.4} /><circle cx={19} cy={12} r={2.4} /></g>
        : <path d={ICONS[icon]} fill="none" stroke={inkOf(t.button)} strokeWidth={2.6} strokeLinecap="round" strokeLinejoin="round" />}
    </svg>
  </div>
)

// A game on a round panel: `board` in the square inside the circle, `top` in
// the arc above it, `bottom` in the arc below, `left` and `right` round keys
// beside it at its middle.
export const RoundTable = ({ room, t, top, board, bottom, left, right }: any) => {
  const key = Math.min(56, room.x - 14)
  const keyAt = Math.round(room.H / 2 - key / 2)
  const keyX = Math.max(14, room.x - key - 8)
  return (
    <div className={`relative w-[${room.W}px] h-[${room.H}px] ${t.page}`}>
      <div className={`absolute left-0 top-0 w-[${room.W}px] h-[${room.y}px] flex flex-col items-center justify-end pb-[6px]`}>{top}</div>
      <div className={`absolute left-[${room.x}px] top-[${room.y}px] w-[${room.side}px] h-[${room.side}px] flex items-center justify-center`}>{board}</div>
      <div className={`absolute left-0 top-[${room.y + room.side}px] w-[${room.W}px] h-[${room.H - room.y - room.side}px] flex justify-center pt-[6px]`}>{bottom}</div>
      {left ? <div className={`absolute left-[${keyX}px] top-[${keyAt}px]`}>{left}</div> : null}
      {right ? <div className={`absolute left-[${room.W - keyX - key}px] top-[${keyAt}px]`}>{right}</div> : null}
    </div>
  )
}

// The one button of the arc below the board, as wide as the arc allows: a
// finger tall, lower where the circle closes in too soon for its words (a
// small round panel), and its words smaller only if that is not enough.
export const RoundButton = ({ room, ui, className, onClick, children }: any) => {
  const words = String(children)
  const wide = (h: number) => Math.min(room.chord(room.side / 2 + 6 + h), Math.round(room.side * 0.6))
  const most = (h: number) => (h >= 44 ? ui.text : Math.min(ui.text, Math.round(h * 0.45)))
  let h = Math.min(ui.button, 44)
  while (h > 30 && wide(h) < fitWidth(words, most(h))) h -= 2
  const w = wide(h)
  const size = fitText(words, w, most(h))
  return (
    <div className={`w-[${w}px] h-[${h}px] rounded-full flex items-center justify-center whitespace-nowrap text-[${size}px] font-semibold ${className}`}
      onClick={onClick}>
      {children}
    </div>
  )
}
